public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing Contact by email address (case-insensitive, leading/trailing spaces ignored). Returns the earliest-created matching Contact, or found = false when there is no match.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Collect the distinct emails to look up, normalized (trimmed and lowercased).
        Set<String> emailsToFind = new Set<String>();
        for (Request req : requests) {
            String normalized = normalizeEmail(req == null ? null : req.email);
            if (normalized != null) {
                emailsToFind.add(normalized);
            }
        }

        // Single SOQL query for the whole batch. SOQL string comparisons are
        // case-insensitive, so this returns every casing of each requested email.
        // Because this class is declared "with sharing", only Contacts visible
        // to the running user are returned.
        Map<String, Contact> earliestContactByEmail = new Map<String, Contact>();
        if (!emailsToFind.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailsToFind
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalizeEmail(c.Email);
                // Results are ordered by CreatedDate, so the first Contact seen
                // for an email is the earliest-created one.
                if (key != null && !earliestContactByEmail.containsKey(key)) {
                    earliestContactByEmail.put(key, c);
                }
            }
        }

        // Build exactly one Result per Request, preserving the request order.
        for (Request req : requests) {
            Result res = new Result();
            String normalized = normalizeEmail(req == null ? null : req.email);
            Contact match = (normalized == null) ? null : earliestContactByEmail.get(normalized);
            if (match != null) {
                res.contactId = match.Id;
                res.found = true;
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }

        return results;
    }

    // Returns the trimmed, lowercased email, or null when the email is null or blank.
    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }

    public class Request {
        @InvocableVariable(required=true label='Email' description='Email address of the Contact to find.')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the Contact found, or null when no Contact matches.')
        public Id contactId;

        @InvocableVariable(label='Found' description='True when a Contact with the given email was found.')
        public Boolean found;
    }
}
