public class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name cannot be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name cannot be null or blank.');
        }

        // Case-insensitive lookup for the object
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sobjType = null;
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                sobjType = globalDescribe.get(key);
                break;
            }
        }
        if (sobjType == null) {
            throw new PicklistServiceException('Object not found: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDescribe = sobjType.getDescribe();

        // Case-insensitive lookup for the field
        Map<String, Schema.SObjectField> fieldsMap = objDescribe.fields.getMap();
        Schema.SObjectField fieldToken = null;
        for (String key : fieldsMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                fieldToken = fieldsMap.get(key);
                break;
            }
        }
        if (fieldToken == null) {
            throw new PicklistServiceException('Field not found on object ' + objectApiName + ': ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        String defaultValue = (String) fieldDescribe.getDefaultValue();

        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
        List<PicklistService.Option> options = new List<PicklistService.Option>();

        for (Schema.PicklistEntry entry : entries) {
            if (entry.isActive()) {
                String val = entry.getValue();
                String lbl = entry.getLabel();
                Boolean isDef = false;

                if (String.isNotBlank(defaultValue)) {
                    if (fieldType == Schema.DisplayType.MULTIPICKLIST) {
                        Set<String> defaultSet = new Set<String>(defaultValue.split(';'));
                        isDef = defaultSet.contains(val);
                    } else {
                        isDef = defaultValue.equals(val);
                    }
                }

                options.add(new Option(val, lbl, isDef));
            }
        }

        return options;
    }
}
