/**
 * Publishes shipment information as FB_Shipment_Event__e platform events,
 * decoupling the warehouse integration from order processing.
 */
public with sharing class ShipmentEventPublisher {

    /**
     * Represents a single shipment to be published as a platform event.
     */
    public class Shipment {
        public String orderNumber;
        public String trackingNumber;
        public String carrier;

        public Shipment(String orderNumber, String trackingNumber, String carrier) {
            this.orderNumber = orderNumber;
            this.trackingNumber = trackingNumber;
            this.carrier = carrier;
        }
    }

    /**
     * Publishes one FB_Shipment_Event__e per shipment using a single publish call.
     * Shipments with a blank order number are skipped.
     *
     * @param shipments shipments to publish; may be null or empty
     * @return the number of events that were published successfully
     */
    public static Integer publishShipments(List<Shipment> shipments) {
        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> eventsToPublish = new List<FB_Shipment_Event__e>();
        for (Shipment shipment : shipments) {
            if (shipment == null || String.isBlank(shipment.orderNumber)) {
                continue;
            }

            FB_Shipment_Event__e event = new FB_Shipment_Event__e();
            event.Order_Number__c = shipment.orderNumber;
            event.Tracking_Number__c = shipment.trackingNumber;
            event.Carrier__c = shipment.carrier;
            eventsToPublish.add(event);
        }

        if (eventsToPublish.isEmpty()) {
            return 0;
        }

        // A single publish call for the whole batch.
        List<Database.SaveResult> saveResults = EventBus.publish(eventsToPublish);

        Integer publishedCount = 0;
        for (Database.SaveResult saveResult : saveResults) {
            if (saveResult.isSuccess()) {
                publishedCount++;
            }
        }
        return publishedCount;
    }
}
