/**
 * Handles FB_Shipment_Event__e platform events and marks the matching
 * FB_Sales_Order__c records as shipped.
 */
public with sharing class ShipmentEventHandler {

    private static final String STATUS_SHIPPED = 'Shipped';
    private static final String STATUS_CANCELLED = 'Cancelled';

    /**
     * Marks the orders referenced by the given events as shipped.
     *
     * - Events with a blank or unknown order number are ignored.
     * - Cancelled orders are never changed.
     * - When several events refer to the same order, the last one in the list wins.
     * - Uses a single SOQL query and a single DML statement per call,
     *   regardless of the number of events.
     *
     * @param events the platform events to process
     */
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Gather the distinct order numbers referenced by the events.
        Set<String> orderNumbers = new Set<String>();
        for (FB_Shipment_Event__e event : events) {
            if (event != null && !String.isBlank(event.Order_Number__c)) {
                orderNumbers.add(event.Order_Number__c.toUpperCase());
            }
        }

        if (orderNumbers.isEmpty()) {
            return;
        }

        // Single SOQL query for every event in this call.
        Map<String, FB_Sales_Order__c> ordersByNumber = new Map<String, FB_Sales_Order__c>();
        for (FB_Sales_Order__c order : [
                SELECT Id, Order_Number__c, Status__c
                FROM FB_Sales_Order__c
                WHERE Order_Number__c IN :orderNumbers
        ]) {
            ordersByNumber.put(order.Order_Number__c.toUpperCase(), order);
        }

        // Apply the events in list order so the last event for an order wins.
        Date shippedDate = Date.today();
        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();
        Set<Id> orderIdsToUpdate = new Set<Id>();

        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }

            FB_Sales_Order__c order = ordersByNumber.get(event.Order_Number__c.toUpperCase());
            if (order == null || order.Status__c == STATUS_CANCELLED) {
                // Unknown order numbers are ignored; cancelled orders are never changed.
                continue;
            }

            order.Status__c = STATUS_SHIPPED;
            order.Tracking_Number__c = event.Tracking_Number__c;
            order.Carrier__c = event.Carrier__c;
            order.Shipped_Date__c = shippedDate;

            if (orderIdsToUpdate.add(order.Id)) {
                ordersToUpdate.add(order);
            }
        }

        // Single DML statement for every event in this call.
        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }
}
