public without sharing class LogPurgeJob implements Schedulable {

    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        DateTime standardCutoff = DateTime.now().addDays(-STANDARD_RETENTION_DAYS);
        DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE ((Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :standardCutoff)
               OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
        ];

        if (!logsToDelete.isEmpty()) {
            List<Database.DeleteResult> results = Database.delete(logsToDelete, false);
            for (Database.DeleteResult result : results) {
                if (!result.isSuccess()) {
                    for (Database.Error error : result.getErrors()) {
                        System.debug(LoggingLevel.ERROR, 'Failed to delete log record ' + result.getId() + ': ' + error.getMessage());
                    }
                }
            }
        }
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
