public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Initialize every requested account to 0 so that accounts with no
        // qualifying opportunities (or only null amounts) are never null.
        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        // Single aggregate query: sums are computed in the database.
        List<AggregateResult> aggregates = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ];

        for (AggregateResult ar : aggregates) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal total = (Decimal) ar.get('totalAmount');
            result.put(accountId, total == null ? 0 : total);
        }

        return result;
    }
}
