public class CaseEscalationService {

    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Escalation reason must not be blank.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        ICasesSelector selector = CasesSelector.newInstance();
        List<Case> cases = selector.selectById(caseIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Date tomorrow = Date.today().addDays(1);
        Boolean hasWork = false;

        for (Case c : cases) {
            if (c.Status == 'Closed' || c.IsEscalated == true) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            Task escalationTask = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = tomorrow,
                Priority = 'High'
            );
            uow.registerNew(escalationTask);

            hasWork = true;
        }

        if (hasWork) {
            uow.commitWork();
        }
    }
}
