public with sharing class ContactPhoneCleanup {
    /**
     * Normalizes Contact.Phone to digits and '+' only.
     * Returns a map of contact Id to first update error for records that failed.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failureMessagesByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failureMessagesByContactId;
        }

        Set<Id> contactIdSet = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                contactIdSet.add(contactId);
            }
        }

        if (contactIdSet.isEmpty()) {
            return failureMessagesByContactId;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIdSet
            WITH USER_MODE
        ];

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contact : contacts) {
            if (String.isNotBlank(contact.Phone)) {
                contact.Phone = contact.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(contact);
            }
        }

        if (contactsToUpdate.isEmpty()) {
            return failureMessagesByContactId;
        }

        List<Database.SaveResult> saveResults = Database.update(contactsToUpdate, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult saveResult = saveResults.get(i);
            if (!saveResult.isSuccess()) {
                String firstErrorMessage = saveResult.getErrors().isEmpty()
                    ? 'Unknown error'
                    : saveResult.getErrors().get(0).getMessage();
                failureMessagesByContactId.put(contactsToUpdate.get(i).Id, firstErrorMessage);
            }
        }

        return failureMessagesByContactId;
    }
}
