public with sharing class ErpCustomerSync {

    /**
     * Entry point from AccountTrigger.
     * Enqueues a Queueable to perform the ERP callouts asynchronously,
     * because callouts are not permitted in an after insert trigger
     * (uncommitted work pending).
     */
    public static void syncNewAccounts(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }
        System.enqueueJob(new ErpCustomerSyncQueueable(accounts));
    }

    /**
     * Wrapper class for the ERP JSON payload.
     */
    private class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(String salesforceId, String name, String country) {
            this.salesforceId = salesforceId;
            this.name = name;
            this.country = country;
        }
    }

    /**
     * Queueable that performs one callout per account.
     * Implements chunking to respect the 100-callout limit per async transaction.
     */
    public class ErpCustomerSyncQueueable implements Queueable, Database.AllowsCallouts {
        private List<Account> accounts;

        public ErpCustomerSyncQueueable(List<Account> accounts) {
            this.accounts = accounts;
        }

        public void execute(QueueableContext context) {
            List<Account> remainingAccounts = new List<Account>();
            Integer calloutsMade = Limits.getCallouts();
            Integer maxCallouts = Limits.getLimitCallouts();

            for (Account acc : accounts) {
                if (calloutsMade < maxCallouts) {
                    syncSingleAccount(acc);
                    calloutsMade++;
                } else {
                    remainingAccounts.add(acc);
                }
            }

            // If we hit the callout limit, enqueue the rest in a new transaction
            if (!remainingAccounts.isEmpty()) {
                System.enqueueJob(new ErpCustomerSyncQueueable(remainingAccounts));
            }
        }

        /**
         * Sends a single account to the ERP as a JSON array with one element.
         */
        private void syncSingleAccount(Account acc) {
            CustomerPayload payload = new CustomerPayload(
                acc.Id,
                acc.Name,
                String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry
            );

            List<CustomerPayload> payloadList = new List<CustomerPayload>{ payload };
            String jsonBody = JSON.serialize(payloadList);

            HttpRequest req = new HttpRequest();
            req.setEndpoint('callout:ERP/api/customers');
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(jsonBody);

            Http http = new Http();
            // Response handling (202 Accepted) is intentionally minimal as error handling is out of scope
            http.send(req);
        }
    }
}
```

