```apex
/**
 * Creates a follow-up Task for every Opportunity that comes out of the
 * weekly pipeline review.
 *
 * Bulk-safe by design: a single SOQL query for the whole batch and a single
 * bulk DML statement, so a call with 150-250 (or more) Opportunity Ids stays
 * far away from the governor limits.
 *
 * Partial success by design: Tasks are inserted with Database.insert(...,
 * false) (allOrNone = false), so a Task rejected by a compliance validation
 * rule does not stop the other Tasks from being created. The Ids of the
 * Opportunities whose Task could not be created are returned to the caller.
 */
public with sharing class FollowUpTaskService {

    private static final Integer FOLLOW_UP_DAYS = 7;

    /**
     * Creates one follow-up Task per Opportunity.
     *
     * @param opportunityIds Ids of the Opportunities to create a follow-up Task for
     * @return the Ids of the Opportunities whose Task could not be created;
     *         an empty Set when every Task was created successfully
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // De-duplicate the input and drop nulls so a single Opportunity never
        // gets two identical follow-up Tasks.
        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }
        if (uniqueOpportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // One SOQL statement for the whole batch (bulk-safe).
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueOpportunityIds
        ]);

        Date activityDate = Date.today().addDays(FOLLOW_UP_DAYS);

        List<Task> tasksToInsert = new List<Task>();
        // Database.insert returns one SaveResult per record, in the same order
        // as the records passed in. This parallel list maps each result index
        // back to the Opportunity that produced the Task.
        List<Id> opportunityIdByTaskIndex = new List<Id>();

        for (Id opportunityId : uniqueOpportunityIds) {
            Opportunity opportunity = opportunitiesById.get(opportunityId);

            // The Opportunity does not exist or is not visible to the running
            // user, so no Task can be created for it.
            if (opportunity == null) {
                failedOpportunityIds.add(opportunityId);
                continue;
            }

            tasksToInsert.add(new Task(
                WhatId       = opportunity.Id,
                OwnerId      = opportunity.OwnerId,
                Subject      = 'Follow up: ' + opportunity.Name,
                ActivityDate = activityDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
            opportunityIdByTaskIndex.add(opportunity.Id);
        }

        if (tasksToInsert.isEmpty()) {
            return failedOpportunityIds;
        }

        // One bulk DML statement with allOrNone = false (partial success):
        // - costs a single DML statement no matter how many Tasks are inserted
        //   (inserting one Task per statement would hit the 150 DML statements
        //   per transaction governor limit at 150+ Opportunities);
        // - a Task rejected by a validation rule fails only its own SaveResult
        //   and does not stop the other Tasks from being created.
        List<Database.SaveResult> saveResults = Database.insert(tasksToInsert, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult saveResult = saveResults[i];
            if (!saveResult.isSuccess()) {
                Id failedOpportunityId = opportunityIdByTaskIndex[i];
                failedOpportunityIds.add(failedOpportunityId);
                for (Database.Error error : saveResult.getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'Follow-up Task for Opportunity ' + failedOpportunityId +
                        ' was not created: ' + String.valueOf(error.getStatusCode()) +
                        ' - ' + error.getMessage()
                    );
                }
            }
        }

        return failedOpportunityIds;
    }
}
```

