import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage = null;

    debounceTimeout = null;
    requestId = 0;
    isComponentConnected = false;

    connectedCallback() {
        this.isComponentConnected = true;
    }

    disconnectedCallback() {
        this.isComponentConnected = false;
        this.clearPendingSearch();
        // Invalidate any in-flight request so its response cannot update the DOM.
        this.requestId += 1;
    }

    handleChange(event) {
        const searchTerm = (event.target.value || '').trim();

        this.clearPendingSearch();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            // Invalidate in-flight requests and clear the results.
            this.requestId += 1;
            this.contacts = [];
            this.errorMessage = null;
            return;
        }

        this.debounceTimeout = setTimeout(() => {
            this.debounceTimeout = null;
            this.executeSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    async executeSearch(searchTerm) {
        if (!this.isComponentConnected) {
            return;
        }

        const currentRequestId = ++this.requestId;

        try {
            const result = await searchContacts({ searchTerm });

            if (!this.isComponentConnected || currentRequestId !== this.requestId) {
                return;
            }

            this.contacts = result || [];
            this.errorMessage = null;
        } catch (error) {
            if (!this.isComponentConnected || currentRequestId !== this.requestId) {
                return;
            }

            this.contacts = [];
            this.errorMessage =
                (error && error.body && error.body.message) ||
                'An unexpected error occurred.';
        }
    }

    clearPendingSearch() {
        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = null;
        }
    }

    get hasResults() {
        return this.contacts && this.contacts.length > 0;
    }
}
