import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60 * 1000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;

    _intervalId = null;
    _inFlight = false;
    _isConnected = false;

    // Stable reference so the same function can be removed in disconnectedCallback.
    _handleVisibilityChange = () => {
        if (!this._isConnected) {
            return;
        }
        // When the tab becomes visible again, load immediately.
        // While hidden, do nothing here; the interval tick also skips requests.
        if (document.visibilityState === 'visible') {
            this.loadStats();
        }
    };

    get hasStats() {
        // Allow a legitimate 0 waiting count.
        return this.waiting !== undefined && this.waiting !== null;
    }

    connectedCallback() {
        // Ensure only one polling loop even if the same node is reconnected.
        if (this._isConnected) {
            return;
        }
        this._isConnected = true;

        document.addEventListener('visibilitychange', this._handleVisibilityChange);

        // Load immediately on insert (imperative Apex, no parameters).
        this.loadStats();

        // Refresh every 60 seconds. The tick skips while hidden or a request is in flight.
        this._intervalId = setInterval(() => {
            if (!this._isConnected) {
                return;
            }
            // Never make requests while the page is hidden.
            if (document.visibilityState === 'hidden') {
                return;
            }
            this.loadStats();
        }, POLL_INTERVAL_MS);
    }

    disconnectedCallback() {
        this._isConnected = false;

        // Stop all polling.
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }

        // Remove the visibilitychange listener so nothing keeps running.
        document.removeEventListener('visibilitychange', this._handleVisibilityChange);
    }

    loadStats() {
        if (!this._isConnected) {
            return;
        }
        // Make no requests while hidden (covers insert and visibility paths).
        if (document.visibilityState === 'hidden') {
            return;
        }
        // Never start a request while the previous one is still in flight; skip.
        if (this._inFlight) {
            return;
        }

        this._inFlight = true;

        getQueueStats()
            .then((result) => {
                if (!this._isConnected) {
                    return;
                }
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                // Remove the error after the next successful refresh.
                this.errorMessage = null;
            })
            .catch((error) => {
                if (!this._isConnected) {
                    return;
                }
                this.errorMessage =
                    error?.body?.message ?? 'Failed to load queue stats.';
            })
            .finally(() => {
                this._inFlight = false;
            });
    }
}
