import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        const source = Array.isArray(value) ? value : [];
        // Work on our own copies so the parent's array and task objects are never mutated.
        // A new array from the parent replaces the whole list.
        this._tasks = source.map((task) => ({ ...task }));
        this.items = source.map((task) => ({ ...task }));
    }

    // Display-only transformation: the public `heading` value is never written to,
    // and later changes from the parent are always reflected (upper-cased).
    get displayHeading() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            // Empty or whitespace-only labels are ignored: nothing added, no event.
            return;
        }
        // Reassign the array (instead of mutating it) so the change is reactive.
        this.items = [...this.items, { id: this.generateId(), label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        // data-id is always a string, even when the task id is a number.
        // Replace the list so the toggle is reactive and the counter updates.
        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }

    generateId() {
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));
        return id;
    }
}
