/**
 * Service that converts an open NPSP donation (pledge) into a monthly
 * installment plan by rebuilding the opportunity's unpaid payments.
 *
 * With Payments enabled, NPSP automatically creates one unpaid payment for the
 * full amount of every new open donation. This service replaces those unpaid
 * payments with an even installment schedule, while paid and written-off
 * payments (the history) are left untouched.
 *
 * The class runs without sharing because it must see and rebuild every payment
 * on the opportunity regardless of how individual payment records are shared.
 * The Apex action that exposes this service should be restricted to authorized
 * major-gift officers.
 */
public without sharing class PaymentPlanService {

    /** Thrown when an installment plan cannot be created; nothing is changed. */
    public class PaymentPlanException extends Exception {}

    /**
     * Replaces the unpaid, not-written-off payments on an open opportunity with
     * numberOfPayments new unpaid installments.
     *
     * Installment i (0-based) is scheduled on firstPaymentDate.addMonths(i).
     * Each installment receives the outstanding amount (the opportunity Amount
     * minus the amounts of its paid and written-off payments) divided by
     * numberOfPayments, rounded down to the cent (RoundingMode.DOWN); the last
     * installment also absorbs the remainder, so the new payments add up exactly
     * to the outstanding amount.
     *
     * @param opportunityId    Id of the open opportunity to reschedule
     * @param numberOfPayments number of installments to create, must be at least 1
     * @param firstPaymentDate scheduled date of the first installment
     * @return the inserted payments, in schedule order
     * @throws PaymentPlanException if numberOfPayments is null or less than 1,
     *         the opportunity is closed, or the outstanding amount is not greater
     *         than zero; in all of these cases nothing is changed
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        // Validate every input before querying or changing anything, so that a
        // failure leaves the opportunity exactly as it was.
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be at least 1, but was: ' + numberOfPayments);
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('firstPaymentDate must not be null.');
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('opportunityId must not be null.');
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed,
                (SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
                FROM npe01__OppPayment__r)
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        Opportunity opportunity = opportunities[0];

        if (opportunity.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments on a closed opportunity: ' + opportunity.Id);
        }

        // Paid and written-off payments are history: keep them and count their
        // amounts as already settled. Every other payment is replaced.
        Decimal settledAmount = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c payment : opportunity.npe01__OppPayment__r) {
            if (payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true) {
                if (payment.npe01__Payment_Amount__c != null) {
                    settledAmount += payment.npe01__Payment_Amount__c;
                }
            } else {
                paymentsToDelete.add(payment);
            }
        }

        Decimal opportunityAmount = opportunity.Amount == null ? 0 : opportunity.Amount;
        Decimal outstandingAmount = opportunityAmount - settledAmount;
        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero, but was: ' + outstandingAmount);
        }

        // Even installments, rounded down to the cent; the last installment also
        // absorbs the remainder so the installments total the outstanding amount.
        Decimal installmentAmount = outstandingAmount.divide(numberOfPayments, 2, RoundingMode.DOWN);
        Decimal lastInstallmentAmount = outstandingAmount - (installmentAmount * (numberOfPayments - 1));

        List<npe01__OppPayment__c> installments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            installments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunity.Id,
                npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastInstallmentAmount : installmentAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        // Apex DML is all-or-nothing: if either statement fails, the transaction
        // rolls back and the opportunity is left exactly as it was.
        delete paymentsToDelete;
        insert installments;

        return installments;
    }
}
