public with sharing class FamilyService {
    private static final String PARENT_TYPE = 'Parent';
    private static final String CURRENT_STATUS = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        List<Id> childIds = new List<Id>();
        List<Id> parentIds = new List<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (Map.Entry<Id, Id> entry : parentIdByChildId.entrySet()) {
            Id childId = entry.getKey();
            Id parentId = entry.getValue();

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            childIds.add(childId);
            parentIds.add(parentId);
            contactIds.add(childId);
            contactIds.add(parentId);
        }

        if (childIds.isEmpty()) {
            return;
        }

        // Find any existing relationship between any involved contacts so re-runs are safe.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
                AND npe4__RelatedContact__c IN :contactIds
        ]) {
            addPair(existingPairs, rel.npe4__Contact__c, rel.npe4__RelatedContact__c);
        }

        Set<String> handledPairs = new Set<String>();
        handledPairs.addAll(existingPairs);

        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Integer i = 0; i < childIds.size(); i++) {
            Id childId = childIds[i];
            Id parentId = parentIds[i];

            // Skip when any relationship already exists in either direction,
            // or when this same pair was already queued in this call.
            if (containsPair(handledPairs, childId, parentId)) {
                continue;
            }

            addPair(handledPairs, childId, parentId);

            // NPSP's reciprocal trigger creates the parent -> child record using the
            // Parent lookup: Son, Daughter, or Child based on the child's gender.
            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = PARENT_TYPE,
                npe4__Status__c = CURRENT_STATUS
            ));
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    private static Boolean containsPair(Set<String> pairs, Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        return pairs.contains(first + '|' + second) ||
            pairs.contains(second + '|' + first);
    }

    private static void addPair(Set<String> pairs, Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        pairs.add(first + '|' + second);
        pairs.add(second + '|' + first);
    }
}
