```apex
/**
 * Trigger Action for the Trigger Actions Framework (TAF) 0.3.4.
 * Registered (After Insert on Account) via the Trigger_Action__mdt record
 * TA_Account_CreateOnboardingTask.
 *
 * When an Account is created with Type 'Customer - Direct' or
 * 'Customer - Channel', an onboarding Task is created for the Account's owner.
 *
 * Bulk safe: builds all Tasks for the batch and inserts them with a single DML
 * statement per trigger execution. Performs no DML at all when no Account
 * qualifies.
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    private static final String TASK_SUBJECT = 'Onboard new customer';
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_PRIORITY = 'Normal';
    private static final Integer DAYS_UNTIL_DUE = 7;

    private static final Set<String> CUSTOMER_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> newList) {
        Date dueDate = Date.today().addDays(DAYS_UNTIL_DUE);
        List<Task> tasksToInsert = new List<Task>();

        for (SObject record : newList) {
            Account account = (Account) record;

            if (String.isBlank(account.Type) || !CUSTOMER_ACCOUNT_TYPES.contains(account.Type)) {
                continue;
            }

            tasksToInsert.add(new Task(
                Subject = TASK_SUBJECT,
                WhatId = account.Id,
                OwnerId = account.OwnerId,
                ActivityDate = dueDate,
                Status = TASK_STATUS,
                Priority = TASK_PRIORITY
            ));
        }

        // Single DML statement for the whole batch; skipped entirely when empty.
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
