public inherited sharing class ContactImportService {
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Bypass only the welcome task action so existing customers
        // do not receive welcome tasks during the migration
        MetadataTriggerHandler.bypass('TA_Contact_CreateWelcomeTask');

        try {
            // Single DML statement for all contacts.
            // TA_Contact_FormatPhone (before insert) and any other Contact
            // automation still run because they are not bypassed.
            insert contacts;
        } finally {
            // Ensure the bypass is cleared when the method exits so that
            // contacts inserted later in the same transaction receive
            // their welcome tasks as usual.
            MetadataTriggerHandler.clearBypass('TA_Contact_CreateWelcomeTask');
        }
    }
}
