@IsTest
public class TA_Opportunity_GuardAmountDecreaseTest {
    private static Opportunity buildOpportunity(Id id, Decimal amount) {
        return new Opportunity(Id = id, Amount = amount);
    }

    private static Id fakeOpportunityId() {
        return TriggerTestUtility.getFakeId(Opportunity.getSObjectType());
    }

    @IsTest
    static void beforeUpdate_rejectsReductionGreaterThanHalf() {
        String expectedMessage = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;
        Id oppId = fakeOpportunityId();
        Opportunity oldOpp = buildOpportunity(oppId, 1000);
        Opportunity newOpp = buildOpportunity(oppId, 499);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        System.assert(newOpp.hasErrors(), 'Expected an error when Amount is reduced by more than half.');
        System.assertEquals(1, newOpp.getErrors().size(), 'Expected exactly one error.');
        System.assertEquals(expectedMessage, newOpp.getErrors()[0].getMessage(), 'Error message should match ERROR_MESSAGE.');
    }

    @IsTest
    static void beforeUpdate_allowsReductionExactlyHalf() {
        Id oppId = fakeOpportunityId();
        Opportunity oldOpp = buildOpportunity(oppId, 1000);
        Opportunity newOpp = buildOpportunity(oppId, 500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        System.assert(!newOpp.hasErrors(), 'A reduction of exactly half should be accepted.');
        System.assert(newOpp.getErrors().isEmpty(), 'Expected no errors.');
    }

    @IsTest
    static void beforeUpdate_allowsIncrease() {
        Id oppId = fakeOpportunityId();
        Opportunity oldOpp = buildOpportunity(oppId, 100);
        Opportunity newOpp = buildOpportunity(oppId, 200);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        System.assert(!newOpp.hasErrors(), 'An increase should be accepted.');
        System.assert(newOpp.getErrors().isEmpty(), 'Expected no errors.');
    }

    @IsTest
    static void beforeUpdate_allowsNullPreviousAmount() {
        Id oppId = fakeOpportunityId();
        Opportunity oldOpp = buildOpportunity(oppId, null);
        Opportunity newOpp = buildOpportunity(oppId, 50);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        System.assert(!newOpp.hasErrors(), 'A null previous Amount should be accepted without an exception.');
        System.assert(newOpp.getErrors().isEmpty(), 'Expected no errors.');
    }

    @IsTest
    static void beforeUpdate_bulkOnlyViolatingRecordsGetError() {
        String expectedMessage = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;

        Id violatingId1 = fakeOpportunityId();
        Id allowedId1 = fakeOpportunityId();
        Id allowedId2 = fakeOpportunityId();
        Id violatingId2 = fakeOpportunityId();
        Id nullPreviousId = fakeOpportunityId();

        Opportunity violatingNew1 = buildOpportunity(violatingId1, 499);
        Opportunity violatingOld1 = buildOpportunity(violatingId1, 1000);

        Opportunity allowedNew1 = buildOpportunity(allowedId1, 500);
        Opportunity allowedOld1 = buildOpportunity(allowedId1, 1000);

        Opportunity allowedNew2 = buildOpportunity(allowedId2, 250);
        Opportunity allowedOld2 = buildOpportunity(allowedId2, 100);

        Opportunity violatingNew2 = buildOpportunity(violatingId2, 100);
        Opportunity violatingOld2 = buildOpportunity(violatingId2, 1000);

        Opportunity nullPreviousNew = buildOpportunity(nullPreviousId, 75);
        Opportunity nullPreviousOld = buildOpportunity(nullPreviousId, null);

        List<Opportunity> triggerNew = new List<Opportunity>{
            violatingNew1,
            allowedNew1,
            allowedNew2,
            violatingNew2,
            nullPreviousNew
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            violatingOld1,
            allowedOld1,
            allowedOld2,
            violatingOld2,
            nullPreviousOld
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(violatingNew1.hasErrors(), 'First violating record should have an error.');
        System.assertEquals(1, violatingNew1.getErrors().size(), 'First violating record should have exactly one error.');
        System.assertEquals(expectedMessage, violatingNew1.getErrors()[0].getMessage(), 'First violating record error message should match ERROR_MESSAGE.');

        System.assert(violatingNew2.hasErrors(), 'Second violating record should have an error.');
        System.assertEquals(1, violatingNew2.getErrors().size(), 'Second violating record should have exactly one error.');
        System.assertEquals(expectedMessage, violatingNew2.getErrors()[0].getMessage(), 'Second violating record error message should match ERROR_MESSAGE.');

        System.assert(!allowedNew1.hasErrors(), 'Exactly-half reduction should not have an error.');
        System.assert(allowedNew1.getErrors().isEmpty(), 'Exactly-half reduction should have no errors.');

        System.assert(!allowedNew2.hasErrors(), 'Increase should not have an error.');
        System.assert(allowedNew2.getErrors().isEmpty(), 'Increase should have no errors.');

        System.assert(!nullPreviousNew.hasErrors(), 'Null previous Amount should not have an error.');
        System.assert(nullPreviousNew.getErrors().isEmpty(), 'Null previous Amount should have no errors.');
    }
}
